from pathlib import Path

p = Path("V1.html")
h = p.read_text(encoding="utf-8-sig")
h = h.replace("V1.14.2", "V1.14.3")

style_marker = "    .checkRow.recommendRow{background:#f5f2ea}"
style_add = '    .checkRow.recommendRow{background:#f5f2ea}\n    #shopping.shop{max-height:none!important;overflow:visible!important}\n    .choiceBlock{border-top:1px solid #cab692;background:#f4eee5;padding:8px 10px 10px}\n    .choiceTitle{font-size:9px;font-weight:900;text-transform:uppercase;letter-spacing:.55px;color:#76572e;margin-bottom:6px}\n    .choiceSummary{font-size:10px;color:#675846;margin-bottom:7px}\n    .choiceOptions{display:grid;gap:6px}\n    .choiceOption{background:#fffaf1;border:1px solid #d9c7a9;border-radius:8px;padding:7px 9px}\n    .choiceOr{text-align:center;font-size:9px;font-weight:900;color:#8c6a3b;text-transform:uppercase}\n    .optionalPrep{border-top:1px dashed #cbbda5;background:#f7f4ed}\n    .optionalPrep summary{cursor:pointer;padding:8px 10px;font-size:9px;font-weight:900;text-transform:uppercase;letter-spacing:.5px;color:#6d614e}\n    .optionalPrepRows{border-top:1px solid #ded5c6}'
if style_marker not in h:
    raise SystemExit("Could not find V1.14.2 style marker.")
h = h.replace(style_marker, style_add, 1)

marker = "function routeShoppingHtml(s){"
helpers = 'const PREP_CHOICE_RULES_V1143 = {\n  \'plague city\': [{\n    label:\'Hangover cure\',\n    finished:\'hangover cure\',\n    components:[\'bucket of milk\',\'chocolate dust\',\'snape grass\']\n  }]\n};\n\nfunction prepChoiceModelV1143(quest,items){\n  const rules=PREP_CHOICE_RULES_V1143[String(quest||\'\').toLowerCase()]||[];\n  const used=new Set(),choices=[];\n  rules.forEach(rule=>{\n    const finished=items.find(i=>normalizedItemName(i.item)===rule.finished);\n    const components=rule.components\n      .map(n=>items.find(i=>normalizedItemName(i.item)===n))\n      .filter(Boolean);\n    if(finished && components.length===rule.components.length){\n      used.add(finished);\n      components.forEach(i=>used.add(i));\n      choices.push({rule,finished,components});\n    }\n  });\n  return {used,choices};\n}\n\nfunction completedPrepBadgeV1143(i,checked){\n  if(!checked){\n    if(i.created)return \'<span class="prepBadge createBadge">Create</span>\';\n    if(i.obtain)return \'<span class="prepBadge obtain">Obtain</span>\';\n    if(i.recommended)return \'<span class="prepBadge recommendBadge">Recommended</span>\';\n    return \'<span class="prepBadge bring">Bring</span>\';\n  }\n  if(i.created)return \'<span class="prepBadge createBadge">Created</span>\';\n  if(i.obtain)return \'<span class="prepBadge obtain">Obtained</span>\';\n  if(i.recommended)return \'<span class="prepBadge recommendBadge">Done</span>\';\n  return \'<span class="prepBadge bring">Packed</span>\';\n}\n\n'
if helpers not in h:
    if marker not in h:
        raise SystemExit("Could not find routeShoppingHtml.")
    h = h.replace(marker, helpers + marker, 1)

start = h.find("function routeShoppingHtml(s){")
end = h.find("function toggleShopV18", start)
if start < 0 or end < 0:
    raise SystemExit("Could not isolate routeShoppingHtml.")
renderer = 'function routeShoppingHtml(s){\n  const rows=s.shopping||[], steps=routeStepMap(s), groups=new Map();\n\n  const itemQuestMap=new Map();\n  rows.forEach(i=>{\n    const n=normalizedItemName(i.item);\n    if(!itemQuestMap.has(n))itemQuestMap.set(n,[]);\n    splitQuests(i.quests).forEach(q=>itemQuestMap.get(n).push(q));\n  });\n\n  rows.forEach(i=>{\n    const quests=splitQuests(i.quests);\n    const ordered=(quests.length?quests:[\'Other\']).sort((a,b)=>(steps.get(a.toLowerCase())||999)-(steps.get(b.toLowerCase())||999));\n    ordered.forEach(quest=>{\n      if(!groups.has(quest))groups.set(quest,[]);\n      const c=classifyPrepItemV1142(i);\n      const allUses=[...new Set(itemQuestMap.get(normalizedItemName(i.item))||[])];\n      const also=allUses.filter(q=>q.toLowerCase()!==quest.toLowerCase());\n      groups.get(quest).push({...i,quest,also,...c});\n    });\n  });\n\n  const orderedGroups=[...groups.entries()].sort((a,b)=>{\n    const sa=steps.get(a[0].toLowerCase())||999,sb=steps.get(b[0].toLowerCase())||999;\n    return sa-sb || a[0].localeCompare(b[0]);\n  });\n\n  let total=0,done=0;\n  orderedGroups.forEach(([quest,items])=>{\n    const model=prepChoiceModelV1143(quest,items);\n    const normal=items.filter(i=>!model.used.has(i) && i.blocksReady);\n    total+=normal.length;\n    done+=normal.filter(isChecked).length;\n    model.choices.forEach(ch=>{\n      total++;\n      if(isChecked(ch.finished)||ch.components.every(isChecked))done++;\n    });\n  });\n\n  const pct=total?Math.round(done/total*100):100;\n  $(\'shopProgress\').textContent=`${done} / ${total} pre-quest prep - ${pct}%`;\n\n  let html=`<div class="shopProgressBar"><div class="shopProgressFill" style="width:${pct}%"></div></div>`;\n\n  orderedGroups.forEach(([quest,items])=>{\n    const model=prepChoiceModelV1143(quest,items);\n    const mainItems=items.filter(i=>!model.used.has(i) && !i.recommended);\n    const optionalItems=items.filter(i=>!model.used.has(i) && i.recommended);\n\n    const blocking=mainItems.filter(i=>i.blocksReady);\n    let qTotal=blocking.length+model.choices.length;\n    let qDone=blocking.filter(isChecked).length;\n    model.choices.forEach(ch=>{\n      if(isChecked(ch.finished)||ch.components.every(isChecked))qDone++;\n    });\n    const complete=!qTotal || qDone===qTotal;\n    const step=steps.get(quest.toLowerCase());\n\n    const sortRank=x=>x.blocksReady?1:x.obtain?2:x.created?3:5;\n    mainItems.sort((a,b)=>sortRank(a)-sortRank(b)||String(a.item).localeCompare(String(b.item)));\n\n    html+=`<div class="questShopGroup ${complete?\'complete\':\'\'}">\n      <div class="questShopHead">${step?`<span class="questStep">Step ${step}</span>`:\'\'}\n        <span class="questShopTitle">${esc(quest)}</span>\n        <span class="questDone">${complete?\'Prep ready\':`${qDone}/${qTotal} prep`}</span>\n      </div><div class="questShopRows">`;\n\n    mainItems.forEach(i=>{\n      const key=checklistKey(i),checked=isChecked(i);\n      let rowCls=i.created?\'createRow\':i.obtain?\'obtainRow\':\'\';\n      let meta=\'\';\n      if(i.created)meta=\'<span class="nonBlockingMeta">Created during quest</span>\';\n      else if(i.obtain)meta=\'<span class="nonBlockingMeta">Obtain during quest</span>\';\n\n      html+=`<label class="checkRow ${rowCls} ${checked?\'done\':\'\'}">\n        <input type="checkbox" ${checked?\'checked\':\'\'} onchange="toggleShopV18(this,\'${esc(key)}\')">\n        <span class="itemName">${esc(i.item)}${i.also&&i.also.length?`<span class="alsoNeeded">Also used: ${esc(i.also.join(\', \'))}</span>`:\'\'}${meta}</span>\n        <span>x${esc(i.qty||1)}</span>\n        <span>${completedPrepBadgeV1143(i,checked)}</span>\n      </label>`;\n    });\n\n    model.choices.forEach(ch=>{\n      const f=ch.finished, fChecked=isChecked(f);\n      const compsChecked=ch.components.every(isChecked);\n      html+=`<div class="choiceBlock">\n        <div class="choiceTitle">Choose one prep path - ${esc(ch.rule.label)}</div>\n        <div class="choiceSummary">${fChecked?\'Finished item packed\':compsChecked?\'Ingredients packed\':\'Either bring the finished item or bring all ingredients below.\'}</div>\n        <div class="choiceOptions">\n          <div class="choiceOption">\n            <label class="checkRow ${fChecked?\'done\':\'\'}">\n              <input type="checkbox" ${fChecked?\'checked\':\'\'} onchange="toggleShopV18(this,\'${esc(checklistKey(f))}\')">\n              <span class="itemName">${esc(f.item)}</span>\n              <span>x${esc(f.qty||1)}</span>\n              <span>${completedPrepBadgeV1143({...f,blocksReady:true},fChecked)}</span>\n            </label>\n          </div>\n          <div class="choiceOr">OR</div>\n          <div class="choiceOption">\n            ${ch.components.map(i=>{\n              const checked=isChecked(i);\n              return `<label class="checkRow ${checked?\'done\':\'\'}">\n                <input type="checkbox" ${checked?\'checked\':\'\'} onchange="toggleShopV18(this,\'${esc(checklistKey(i))}\')">\n                <span class="itemName">${esc(i.item)}</span>\n                <span>x${esc(i.qty||1)}</span>\n                <span>${completedPrepBadgeV1143({...i,blocksReady:true},checked)}</span>\n              </label>`;\n            }).join(\'\')}\n          </div>\n        </div>\n      </div>`;\n    });\n\n    if(optionalItems.length){\n      html+=`<details class="optionalPrep">\n        <summary>Optional / convenience - ${optionalItems.length}</summary>\n        <div class="optionalPrepRows">`;\n      optionalItems.forEach(i=>{\n        const checked=isChecked(i);\n        html+=`<label class="checkRow recommendRow ${checked?\'done\':\'\'}">\n          <input type="checkbox" ${checked?\'checked\':\'\'} onchange="toggleShopV18(this,\'${esc(checklistKey(i))}\')">\n          <span class="itemName">${esc(i.item)}<span class="nonBlockingMeta">Recommended, not required</span></span>\n          <span>x${esc(i.qty||1)}</span>\n          <span>${completedPrepBadgeV1143(i,checked)}</span>\n        </label>`;\n      });\n      html+=\'</div></details>\';\n    }\n\n    html+=\'</div></div>\';\n  });\n\n  return html;\n}\n'
h = h[:start] + renderer + h[end:]

p.write_text(h, encoding="utf-8", newline="\n")
print("V1.14.3 prep semantics cleanup applied.")
